draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // Draw brain
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw thought bubble
  ctx.beginPath();
  ctx.arc(W / 2 + 70 + 20 * Math.sin(t), H / 2 - 20 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw stick figure
  ctx.beginPath();
  ctx.arc(W / 2, H - 50, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 40);
  ctx.lineTo(W / 2, H - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 30);
  ctx.lineTo(W / 2 - 20, H - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H - 30);
  ctx.lineTo(W / 2 + 20, H - 40);
  ctx.stroke();

  ctx.restore();
}
